    localStorage.setItem('an_ops', JSON.stringify({ ...NBV.logon.scrub(sh),
      a: $('cA').value, i: $('cI').value, ri: $('cRI').value, auto: $('cAuto').value, autoStart: $('cAutoStart')?.value || 'last', oooiTx: !!$('oooiTx')?.checked, roster }));
