async function genRouteInfo(flt) {
  const data = lastIvaoData || NBV.ivao.last();
  if (!data || (!flt.lat && !flt.lng)) return [];
  const ri = await buildRouteInfo({ callsign: flt.callsign, dep: flt.dep, arr: flt.arr, lat: flt.lat, lon: flt.lng, hdg: flt.heading, alt: flt.alt, gs: flt.gs, data,
    arrLat: flt.arrLat, arrLon: flt.arrLon, arrDist: flt.arrivalDist });
  const cur = flights[flt.callsign] || flt; // durante el await el escaneo pudo sustituir el objeto del vuelo: se anota en el vigente
  const tgt = cur.firstSeen === flt.firstSeen ? cur : flt; // si el callsign ya es otra pierna, el parking de esta no se le pasa
  if (!tgt.assignedParking) tgt.assignedParking = genParking(flt.arr);
  let body = ri.body;
  if (tgt.assignedParking) body += `--- PARKING ASIGNADO ---\n${flt.arr}: ${tgt.assignedParking}\n`;
  return [{ id: 'route_info', label: 'ROUTE INFO', body, significant: ri.nSig > 0 || ri.nPirep > 0 || ri.atcCount >= 4 }];
}

