let scanBusy = false;     // pasada en curso
let lastIvaoData = null;  // último whazzup (para el route info)

// 5.3.1: el simulador da datos recientes (<30 s) de este callsign → el avión sigue vivo aunque IVAO lo omita
function opsSimLive(cs) {
  const local = ($('fsuipcCs')?.value || '').trim().toUpperCase();
  return !!local && local === cs && !!fsuipcGetData(30000);
}

async function scan() {
  const prefix = $('cA').value.trim().toUpperCase();
  if (!prefix || scanBusy) return;
  scanBusy = true;
  try {
    const data = await NBV.ivao.get({ maxAge: 10000 });
    lastIvaoData = data;
    const allPilots = NBV.ivao.pilots(data);
    const nbvPilots = allPilots.filter(p => safeStr(p.callsign).toUpperCase().startsWith(prefix));
    if (nbvPilots.length) {
      log(`${prefix}: ${nbvPilots.length} detectado(s) [${nbvPilots.map(p => `${p.callsign}(${p.lastTrack?.onGround ? 'GND' : 'FL' + Math.round(safeNum(p.lastTrack?.altitude) / 100)} ${NBV.ivao.depOf(p) || '?'}-${NBV.ivao.arrOf(p) || '?'})`).join(', ')}]`, 'ops');
    } else {
      log(`${prefix}: ningún piloto detectado (${allPilots.length} en red)`, '');
    }

    const onlineCs = new Set(nbvPilots.map(p => p.callsign.toUpperCase()));
    await opsTechlogTick(Date.now()); // 5.2: estado técnico de tu avión (TechLog) antes de generar mensajes
    for (const ev of NBV.opsLogic.offline(flights, onlineCs, Date.now(), { simLive: opsSimLive })) { log(`${ev.cs} desconectado de IVAO`, 'wrn'); NBV.flightLog.offline(ev.cs, Date.now()); }

    // v5: la decisión (estado, fase, qué enviar) está en NBV.opsLogic, sin DOM ni red; aquí solo se ejecuta
    const autoSend = $('cAuto').value === '1', riMode = $('cRI').value;
    const decideOpts = { riMode, hasGen: ph => !!PHASE_GEN[ph], wasSentRecently };
    for (const pilot of nbvPilots) {
      const cs = pilot.callsign.toUpperCase();
      const sim = opsSimLive(cs) ? fsuipcGetData() : null; // 5.3.1: velocidad vertical real de tu avión
      const { flt, events } = NBV.opsLogic.update(pilot, flights[cs] || null, { now: Date.now(), pv: phpvmsActive[cs], simVs: sim && typeof sim.verticalSpeed === 'number' ? sim.verticalSpeed : null });
      for (const ev of events) if (ev.type === 'newLeg') log(`${cs}: nueva pierna ${ev.dep}→${ev.arr}`, 'ops');
      flights[cs] = flt;
      fsuipcInjectIntoFlight(flt);
      for (const ev of events) {
        if (ev.type === 'detected') { log(`✈ ${cs} detectado: ${flt.dep}→${flt.arr} (${flt.aircraft})`, 'ops'); NBV.sound.play('detected'); discordNotifyDetected(flt); }
        if (ev.type === 'phase') { log(`${cs}: ${ev.from} → ${ev.to}`, 'ops'); NBV.sound.play('phase'); discordNotifyPhase(flt, ev.from, ev.to); }
      }
      for (const a of NBV.opsLogic.decide(flt, pilot, { ...decideOpts, now: Date.now() })) {
        if (a.type === 'eet') { if (a.min > 0) log(`${cs}: EET estimado ${Math.floor(a.min / 60)}h${String(a.min % 60).padStart(2, '0')}m`, ''); }
        else if (a.type === 'phaseSkip') log(`${cs}: ${a.ph} ya enviado (sesión anterior), omitido`, '');
        else if (a.type === 'phase') processMessages(flt, a.ph, PHASE_GEN[a.ph], autoSend);
        else if (a.type === 'riRestored') log(`${cs}: route info reciente (sesión anterior), restaurado`, '');
        else if (a.type === 'routeinfo') processMessages(flt, a.key, genRouteInfo, autoSend, a.significant);
      }
    }

    await opsTrackDelivery().catch(() => {}); // 5.0 rc2: «esperando al avión» → «entregado HH:MMZ»
    for (const cs of onlineCs) if (flights[cs]) NBV.flightLog.track(flights[cs], Date.now()); // 5.1: registro de vuelos
    await opsRegistroIntegraciones(Date.now()).catch(() => {}); // 5.2: TechLog del vuelo y comprobación de PIREP
    if ($('phpvmsEn')?.checked) phpvmsMergeWithFlights();
    updateDashboard(); updateStats(); updateAoc(); renderRosterChips(); flogRender();
    opsSaveState();
    const n = Object.values(flights).filter(f => !f.offlineSince).length;
    ss('live', `Monitor activo — ${n} vuelo(s) ${prefix} — ${tsShort()}`);
  } catch (e) {
    log(`Scan error: ${e.message}`, 'err');
    ss('err', `✗ ${e.message}`);
  } finally { scanBusy = false; }
}

async function processMessages(flt, phase, generatorFn, autoSend, requireSignificant = false) {
  try {
    const msgs = await generatorFn(flt);
    // 5.0 rc2 (vuelo 1): tras aterrizar el Fenix deja de consultar Hoppie en pocos minutos. Si ya no está
    // conectado, no se envía: se quedaría 24 h en cola y le llegaría en el siguiente vuelo. Queda «retenido».
    const hold = autoSend && phase === 'landed' && !(await opsAircraftOnline(flt.callsign));
    for (const m of msgs) {
      const key = `${phase}_${m.id}`;
      if (requireSignificant && m.significant === false) {
        log(`${m.label} ${flt.callsign}: sin info significativa, omitido`, '');
        recordSent(flt.callsign, flt.dep, flt.arr, phase, m.label, 'skip', m.body, key);
        continue;
      }
      flt.msgStatus[key] = hold ? 'held' : autoSend ? 'sending' : 'pending';
      flt.msgBodies[key] = m.body;
      updateDashboard();
      if (hold) { log(`${m.label} ${flt.callsign}: retenido, el avión ya no está conectado a Hoppie (clic en la tarjeta para enviarlo)`, 'wrn'); recordSent(flt.callsign, flt.dep, flt.arr, phase, m.label, 'held', m.body, key); continue; }
      if (!autoSend) { log(`${m.label} generado para ${flt.callsign} (envío manual)`, ''); continue; }
      try {
        await sendTelex(flt.callsign, m.body, { auto: true });
        flt.msgStatus[key] = 'sent'; (flt.msgSentAt ||= {})[key] = Date.now();
        log(`✓ ${m.label} → ${flt.callsign}`, 'ok');
        recordSent(flt.callsign, flt.dep, flt.arr, phase, m.label, 'sent', m.body, key);
        await sleep(800);
      } catch (e) {
        flt.msgStatus[key] = 'error';
        NBV.sound.play('error');
        log(`✗ ${m.label} → ${flt.callsign}: ${e.message}`, 'err');
        recordSent(flt.callsign, flt.dep, flt.arr, phase, m.label, 'error', m.body, key);
      }
    }
  } catch (e) {
    log(`Error generando ${phase} para ${flt.callsign}: ${e.message}`, 'err');
  }
  updateDashboard(); updateStats();
}

// Conditional version: only sends if the message body contains significant info
// (SIGMETs, PIREPs, or notable ATC changes). Used for 15min post-departure check.


// ── 5.0 rc2: estado real de entrega (Hoppie: hora de recepción y de recogida por el avión) ──
async function opsAircraftOnline(cs) {
  try { return (await NBV.hoppie.online(true)).has(NBV.acars.to(cs).toUpperCase()); }
  catch (e) { return true; } // sin datos de Hoppie: se envía como antes
}
// Hoppie da la recepción como «DD-HH:MMZ» (sin mes ni año): se reconstruye alrededor de `ref` (ms); null si no se puede
function opsHoppieRxMs(rx, ref) {
  const m = /^(\d{1,2})-(\d{2}):(\d{2})Z?$/.exec(String(rx || '').trim());
  if (!m || !ref) return null;
  const d = new Date(ref); let best = null;
  for (const dm of [-1, 0, 1]) { const t = Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + dm, +m[1], +m[2], +m[3]); if (best === null || Math.abs(t - ref) < Math.abs(best - ref)) best = t; }
  return Math.abs(best - ref) < 3 * 86400000 ? best : null;
}
let deliveryAt = 0;
const deliveredIds = new Set(); // 5.5 (G1): ids de Hoppie que ya confirmaron una clave; cada mensaje confirma como mucho una
async function opsTrackDelivery() {
  if (Date.now() - deliveryAt < 55000) return;
  const station = ($('cS')?.value || '').trim().toUpperCase(); if (!station) return;
  const pend = Object.values(flights).filter(f => Object.values(f.msgStatus || {}).includes('sent'));
  if (!pend.length) return;
  deliveryAt = Date.now();
  const net = ((await NBV.hoppie.online()).get(station) || [])[0]?.net || 'IVAO';
  // Texto completo normalizado; un mensaje troceado por hoppieSendTelex se compara con su primer paquete («[1/N] …»)
  const norm = s => String(s || '').replace(/\s+/g, ' ').trim().toUpperCase();
  const firstPacket = body => { const c = splitMsg(sanitizeForHoppie(body), 480); return c.length ? norm(c.length > 1 ? `[1/${c.length}] ${c[0]}` : c[0]) : ''; };
  for (const f of pend) {
    const dest = NBV.acars.to(f.callsign).toUpperCase();
    let h; try { h = await NBV.hoppie.history(dest, net); } catch (e) { continue; }
    const mine = h.filter(x => x.from === station && x.to === dest && x.relayed).sort((a, b) => a.id - b.id);
    const sentAt = f.msgSentAt || {};
    const keys = Object.keys(f.msgStatus).filter(k => f.msgStatus[k] === 'sent').sort((a, b) => (sentAt[a] || 0) - (sentAt[b] || 0));
    for (const k of keys) {
      const want = firstPacket(f.msgBodies?.[k] || '');
      if (!want) continue;
      // Recibido por Hoppie no antes del envío (resolución de minuto, 1 min de margen por el reloj); sin hora legible decide el texto y el id
      const from = sentAt[k] ? Math.floor(sentAt[k] / 60000) * 60000 - 60000 : null;
      const hit = mine.find(x => {
        if (deliveredIds.has(x.id) || norm(x.text) !== want) return false;
        const rx = from === null ? null : opsHoppieRxMs(x.rx, sentAt[k]);
        return rx === null || rx >= from;
      });
      if (hit) { deliveredIds.add(hit.id); f.msgStatus[k] = 'delivered'; (f.msgDelivered ||= {})[k] = hit.relayed; markHistoryDelivered(f.callsign, k, hit.relayed); }
    }
  }
}

// Manual send from dashboard
async function manualSend(cs, key) {
  const flt = flights[cs];
  const body = flt?.msgBodies?.[key];
  if (!body) { log(`${key} → ${cs}: contenido no disponible, regenera el mensaje`, 'wrn'); return; }
  flt.msgStatus[key] = 'sending';
  updateDashboard();
  try {
    await sendTelex(cs, body, { auto: false });
    flt.msgStatus[key] = 'sent'; (flt.msgSentAt ||= {})[key] = Date.now();
    log(`✓ ${key} → ${cs} (manual)`, 'ok');
    recordSent(cs, flt.dep, flt.arr, key.split('_')[0], key, 'sent', body, key);
  } catch (e) {
    flt.msgStatus[key] = 'error';
    log(`✗ ${key} → ${cs}: ${e.message}`, 'err');
  }
  updateDashboard(); updateStats();
}

