// ══════════════════════════════════════════════════════════════════
//  phpVMS INTEGRATION MODULE — OPS Center
// ══════════════════════════════════════════════════════════════════
let phpvmsInterval=null, phpvmsPirepCache={}, phpvmsActive={}, phpvmsScanCount=0, phpvmsScanning=false;
const PHPVMS_CACHE_TTL = 300000;



function phpvmsCallsign(pirep) {
  const prefix = pirep?.airline?.icao||pirep?.airline_icao||'';
  const num = String(pirep?.flight_number||'').padStart(3,'0');
  if (!prefix||!num||num==='000') return null;
  return `${prefix}${num}`.toUpperCase();
}
async function phpvmsFetchGeojson() {
  const r = await NBV.net.req(`${phpvmsBase()}/api/acars/geojson`, { timeout: 15000, headers: await phpvmsHeaders(), cache: 'no-store' });
  if (!r.ok) throw new Error(`phpVMS GeoJSON HTTP ${r.status}`);
  const json = await r.json();
  return json?.data?.features || json?.features || [];
}
async function phpvmsFetchPirep(pirepId) {
  const cached = phpvmsPirepCache[pirepId];
  if (cached && Date.now() - cached.cachedAt < PHPVMS_CACHE_TTL) return cached;
  try {
    const r = await NBV.net.req(`${phpvmsBase()}/api/pireps/${encodeURIComponent(pirepId)}`, { timeout: 10000, headers: await phpvmsHeaders() });
    if (!r.ok) return null;
    const data = (await r.json())?.data;
    if (!data?.id) return null;
    phpvmsPirepCache[pirepId] = { ...data, cachedAt: Date.now() };
    return phpvmsPirepCache[pirepId];
  } catch (e) { return null; }
}
async function phpvmsScan() {
  if (!$('phpvmsEn')?.checked) return;
  if (phpvmsScanning) return; // el intervalo relanza el escaneo aunque el anterior (un fetch por vuelo) aún no haya acabado
  phpvmsScanning = true;
  phpvmsScanCount++;
  try {
    const features = await phpvmsFetchGeojson();
    phpvmsSetStatus(`Scan #${phpvmsScanCount}: ${features.length} vuelo(s) en phpVMS`, true);
    const activePids = new Set();
    for (const feat of features) {
      const props = feat.properties||{}, coords = feat.geometry?.coordinates||[];
      const pirepId = props.pirep_id; if (!pirepId) continue;
      activePids.add(pirepId);
      const lon=parseFloat(coords[0])||0, lat=parseFloat(coords[1])||0;
      const alt=parseFloat(coords[2]??props.alt)||0, hdg=parseFloat(props.heading)||0;
      const pirep = await phpvmsFetchPirep(pirepId);
      const cs = pirep ? phpvmsCallsign(pirep) : null; if (!cs) continue;
      phpvmsActive[cs] = { pirepId, callsign:cs, lat, lon, alt, heading:hdg,
        dep:pirep?.dpt_airport_id||'????', arr:pirep?.arr_airport_id||'????',
        aircraft:pirep?.aircraft?.icao||'????',
        registration:pirep?.aircraft?.registration||'',
        acName:pirep?.aircraft?.name||'',
        route:pirep?.route||'', planFL:pirep?.level||0,
        plannedDistNmi:pirep?.planned_distance?.nmi||0,
        progressPct: (pirep?.planned_distance?.nmi||0) > 0
          ? Math.min(100, Math.round((pirep?.distance?.nmi||0) / pirep.planned_distance.nmi * 100)) : 0,
        phpvmsPhase:pirep?.phase||'',
        arrLat:pirep?.arr_airport?.lat||null, arrLon:pirep?.arr_airport?.lon||null,
        pilotName:pirep?.user?.name||'', pilotIdent:pirep?.user?.ident||'',
        gs:parseFloat(props.gs)||0, onGround:alt<100, srcPhpvms:true, updatedAt:Date.now() };
    }
    // Purgar inactivos
    for (const cs of Object.keys(phpvmsActive)) {
      if (!activePids.has(phpvmsActive[cs]?.pirepId)) delete phpvmsActive[cs];
    }
    const now = Date.now();
    for (const pid of Object.keys(phpvmsPirepCache)) {
      if (now-phpvmsPirepCache[pid].cachedAt>PHPVMS_CACHE_TTL*2) delete phpvmsPirepCache[pid];
    }
    phpvmsMergeWithFlights();
    updateDashboard(); updateStats();
  } catch(e) { phpvmsSetStatus(`✗ ${e.message}`, false); }
  finally { phpvmsScanning = false; }
}
function phpvmsMergeWithFlights() {
  const prefix = ($('cA')?.value.trim().toUpperCase()) || 'NBV';
  for (const [cs, pv] of Object.entries(phpvmsActive)) {
    if (!cs.startsWith(prefix)) continue;
    const f = flights[cs];
    if (f && !f.offlineSince && !f.srcPhpvms) {
      // Vuelo ya visto en IVAO: solo completar datos que falten
      for (const [k, v] of [['pilotName', pv.pilotName], ['pilotIdent', pv.pilotIdent], ['registration', pv.registration],
        ['acName', pv.acName], ['phpvmsRoute', pv.route], ['planFL', pv.planFL]]) if (!f[k] && v) f[k] = v;
      if (pv.progressPct) f.progressPct = pv.progressPct;
      if (pv.arrLat != null) f.arrLat = pv.arrLat;
      if (pv.arrLon != null) f.arrLon = pv.arrLon;
      if (pv.phpvmsPhase) f._phpvmsPhase = pv.phpvmsPhase;
      if (f.dep === '????' && pv.dep !== '????') f.dep = pv.dep;
      if (f.arr === '????' && pv.arr !== '????') f.arr = pv.arr;
      continue;
    }
    // Piloto no conectado a IVAO: tarjeta desde phpVMS
    const synPilot = { lastTrack: { altitude: pv.alt, groundSpeed: pv.gs || 0, onGround: pv.onGround, latitude: pv.lat, longitude: pv.lon, state: '' }, _phpvmsPhase: pv.phpvmsPhase };
    const phase = detectPhase(synPilot, f || null);
    if (!f) { log(`✈ ${cs} [phpVMS]: ${pv.dep}→${pv.arr} | ${pv.pilotName}`, 'ops'); discordNotifyDetected({ callsign: cs, dep: pv.dep, arr: pv.arr, aircraft: pv.aircraft, srcPhpvms: true, pilotName: pv.pilotName }); }
    else if (f.phase !== phase) { log(`${cs}: ${f.phase} → ${phase}`, 'ops'); discordNotifyPhase({ callsign: cs, dep: pv.dep, arr: pv.arr, alt: pv.alt, gs: pv.gs }, f.phase, phase); }
    flights[cs] = { ...(f || {}), callsign: cs, phase, dep: pv.dep, arr: pv.arr, aircraft: pv.aircraft,
      registration: pv.registration, acName: pv.acName, phpvmsRoute: pv.route, planFL: pv.planFL, progressPct: pv.progressPct,
      alt: pv.alt, gs: pv.gs || 0, heading: pv.heading, lat: pv.lat, lng: pv.lon, onGround: pv.onGround,
      pilotName: pv.pilotName, pilotIdent: pv.pilotIdent, arrLat: pv.arrLat, arrLon: pv.arrLon, _phpvmsPhase: pv.phpvmsPhase,
      pirepId: pv.pirepId, srcPhpvms: true, srcSim: false, ivaoState: '', arrivalDist: null,
      firstSeen: f?.firstSeen || Date.now(), lastSeen: Date.now(), offlineSince: null,
      sent: f?.sent || newSent(), msgStatus: f?.msgStatus || {}, msgBodies: f?.msgBodies || {}, msgDelivered: f?.msgDelivered || {}, msgSentAt: f?.msgSentAt || {},
      estEnrouteMin: f?.estEnrouteMin || 0, enrouteStart: f?.enrouteStart || 0, routeInfoCount: f?.routeInfoCount || 0 };
  }
  // Vuelos solo-phpVMS que ya no están activos
  for (const cs of Object.keys(flights)) if (flights[cs].srcPhpvms && !phpvmsActive[cs]) delete flights[cs];
}
