const OPS_STATE_KEY = 'an_ops_state', OPS_STATE_MAX_AGE = 20 * 60000;

function opsSaveState() {
  try {
    const keep = {};
    for (const [cs, f] of Object.entries(flights)) if (Date.now() - (f.lastSeen || 0) < OPS_STATE_MAX_AGE) keep[cs] = f;
    localStorage.setItem(OPS_STATE_KEY, JSON.stringify({ t: Date.now(), running: !!monitorInterval, total: totalMsgsSent, flights: keep }));
  } catch (e) { /* cuota llena: se omite */ }
}

function opsRestoreState() {
  let st = null; try { st = JSON.parse(localStorage.getItem(OPS_STATE_KEY)); } catch (e) {}
  if (!st?.flights) return null;
  let n = 0;
  for (const [cs, f] of Object.entries(st.flights)) {
    if (Date.now() - (f.lastSeen || 0) > OPS_STATE_MAX_AGE) continue;
    // Envíos que quedaron a medias al recargar → pendientes de reenvío manual
    for (const k of Object.keys(f.msgStatus || {})) if (f.msgStatus[k] === 'sending') f.msgStatus[k] = 'error';
    flights[cs] = { ...f, msgBodies: f.msgBodies || {}, msgStatus: f.msgStatus || {} }; n++;
  }
  msgCountRestore(st.total);
  if (n) log(`Estado restaurado: ${n} vuelo(s) de la sesión anterior`, 'ops');
  return st;
}

