// ══════════════════════════════════════════════════════════════════
//  INTEGRACIONES DEL OPS (5.2): TechLog de tu avión y comprobación de PIREP
//  · TechLog (core/20-techlog.js): solo para tu vuelo («Mi callsign» de FSUIPC) y con el OPS abierto desde el
//    servidor local. Estado técnico en la tarjeta, TELEX «TECH STATUS» en el preflight, aviso si la librea
//    cargada no es la matrícula asignada, y la toma y los defectos del vuelo en el registro.
//  · PIREP (core/21-pirep.js): con phpVMS activado, cada pierna completada se contrasta con su PIREP.
// ══════════════════════════════════════════════════════════════════
let techlogLastAt = 0, techlogLastFlightAt = 0, pirepLastAt = 0;
const TECHLOG_EVERY = 60000, PIREP_EVERY = 120000;
const opsOwnCallsign = () => ($('fsuipcCs')?.value || '').trim().toUpperCase();

// Estado técnico de tu avión → tarjeta del vuelo (antes de generar los mensajes de la pasada)
async function opsTechlogTick(now) {
  if (!NBV.techlog.enabled()) return;
  if (!NBV.techlog.available()) { NBV.techlog.setStatus('Abre el OPS con START-ACARS en el PC del simulador para leer TechLog', false); return; }
  if (now - techlogLastAt < TECHLOG_EVERY) return;
  techlogLastAt = now;
  const cs = opsOwnCallsign(), flt = cs ? flights[cs] : null;
  try {
    const s = await NBV.techlog.snapshot();
    const nDef = s.deferred.length + s.open.length;
    NBV.techlog.setStatus(`Conectado · ${s.reg || 'sin avión'} · DISPATCH ${s.dispatch} · ${s.ready}${nDef ? ` · ${nDef} defecto(s)` : ''}${cs ? '' : ' · indica «Mi callsign» en FSUIPC'}`, true);
    if (!flt) return;
    const prev = flt.tech;
    flt.tech = s;
    const planned = String(flt.registration || '').toUpperCase().replace(/-/g, '');
    flt.techMismatch = !!(planned && s.reg && planned !== s.reg.replace(/-/g, ''));
    if (flt.techMismatch && !prev?.mismatchLogged) { log(`TechLog ${cs}: librea cargada ${s.reg}, avión asignado ${flt.registration}`, 'wrn'); s.mismatchLogged = true; }
    else if (prev?.mismatchLogged) s.mismatchLogged = true;
    if (prev && (prev.dispatch !== s.dispatch || prev.ready !== s.ready)) log(`TechLog ${cs}: DISPATCH ${s.dispatch} · ${s.ready}`, s.dispatch === 'GO' ? 'ops' : 'wrn');
  } catch (e) { NBV.techlog.setStatus(e.message, false); }
}

// TELEX «TECH STATUS» del preflight (solo tu vuelo y con TechLog accesible)
async function opsTechStatusMessage(flt) {
  if (!NBV.techlog.enabled() || !NBV.techlog.available() || flt.callsign !== opsOwnCallsign()) return null;
  const s = flt.tech || await NBV.techlog.snapshot();
  return { id: 'techlog', label: 'TECH STATUS', body: NBV.techlog.statusText(s, { cs: flt.callsign, plannedReg: flt.registration }) };
}

// Tras cada pasada: la toma y los defectos de tu vuelo (TechLog) y la comprobación de PIREP (phpVMS)
async function opsRegistroIntegraciones(now) {
  const recent = NBV.flightLog.list('', now).filter(e => now - (e.last || 0) < 24 * 3600000);
  const own = opsOwnCallsign();
  if (own && NBV.techlog.enabled() && NBV.techlog.available() && now - techlogLastFlightAt >= TECHLOG_EVERY) {
    const e = recent.find(x => x.cs === own && x.st === 'completado' && !x.tech?.closed);
    if (e) {
      techlogLastFlightAt = now;
      try {
        const rec = await NBV.techlog.flightFor(e);
        if (rec) {
          NBV.flightLog.annotate(e.id, { tech: rec }, now);
          if (rec.closed) log(`TechLog ${e.cs}: toma ${rec.landing ? rec.landing.vs + ' fpm' : '—'}${rec.defects.length ? ` · ${rec.defects.length} defecto(s) en vuelo` : ''}`, rec.defects.length ? 'wrn' : 'ops');
        }
      } catch (err) { /* TechLog cerrada: se reintenta en la siguiente pasada */ }
    }
  }
  if (!$('phpvmsEn')?.checked || now - pirepLastAt < PIREP_EVERY) return;
  pirepLastAt = now;
  for (const e of recent) {
    if (e.st !== 'completado' || e.pirep?.final) continue;
    let pirep = null;
    if (e.pirepId) { try { pirep = await NBV.pirepCheck.fetchPirep(phpvmsBase(), e.pirepId, await phpvmsHeaders()); } catch (err) { continue; } }
    const r = NBV.pirepCheck.evaluate(e, pirep, now);
    if (!r) continue;
    if (r.label !== e.pirep?.label || (r.issues || []).join() !== (e.pirep?.issues || []).join()) {
      if (r.level === 'wrn' || r.level === 'err') log(`PIREP ${e.cs} ${e.dep}→${e.arr}: ${r.label}${r.issues.length ? ' — ' + r.issues.join('; ') : ''}`, r.level === 'err' ? 'err' : 'wrn');
      else if (r.final) log(`PIREP ${e.cs} ${e.dep}→${e.arr}: ${r.label}`, 'ok');
    }
    NBV.flightLog.annotate(e.id, { pirep: { ...r, at: now } }, now);
  }
}

// «Preparar» un PIREP manual cuando vmsACARS no lo presentó: copia los datos y abre el formulario de phpVMS
async function flogPirepPrep(id) {
  const e = NBV.flightLog.list().find(x => x.id === id);
  if (!e) return;
  const text = NBV.pirepCheck.manualText(e);
  try { await navigator.clipboard.writeText(text); ss('ok', 'Datos del PIREP copiados: pégalos en el formulario de phpVMS'); }
  catch (err) { window.prompt('Copia estos datos para el PIREP manual:', text); }
  window.open(`${phpvmsBase()}/pireps/create`, '_blank', 'noopener');
}

// ── OOOI (5.5): OUT/OFF/ON/IN de tu avión a partir de las muestras de FSUIPC (NBV.oooi, sin DOM) ──
// Un estado por callsign; la hora de cada evento es la de la condición (no la de la muestra). Se guarda en flt.oooi
// (opsSaveState lo conserva) y llega al registro de vuelos. Solo tu avión: «Mi callsign» de FSUIPC con vuelo en el OPS.
const oooiState = {};
function opsOooiSample(sim) {
  const cs = opsOwnCallsign(), flt = cs ? flights[cs] : null;
  if (!flt || !sim) return;
  flt.oooi = flt.oooi || {};
  const now = sim.ts || Date.now();
  // Se reconstruye si falta o si el vuelo perdió tiempos que el estado ya tenía (pierna nueva con el mismo callsign: flt.oooi vuelve a {})
  if (!oooiState[cs] || Object.keys(oooiState[cs].t).some(k => !flt.oooi[k])) oooiState[cs] = NBV.oooi.fromTimes(flt.oooi);
  const r = NBV.oooi.step(oooiState[cs], { onGround: !!sim.onGround, gs: sim.groundSpeed || 0 }, now, { phase: flt.phase });
  oooiState[cs] = r.st;
  if (!r.events.length) return;
  for (const ev of r.events) {
    flt.oooi[ev.type.toLowerCase()] = ev.t;
    log(`OOOI ${cs} ${ev.type} ${new Date(ev.t).toISOString().substring(11, 16)}Z`, 'ops');
  }
  NBV.flightLog.track(flt, Date.now());
  opsSaveState(); // 5.5 (G5): una recarga justo después del evento no lo repite (el escaneo solo guarda al final de cada pasada)
  for (const ev of r.events) opsOooiSend(flt, ev.type).catch(e => log(`OOOI ${cs} ${ev.type}: ${e.message}`, 'err'));
}

// TELEX OOOI a tu avión (opcional, casilla «oooiTx»): uno por evento; el IN lleva el resumen. Dedup por callsign+ruta+evento (6 h, persiste),
// y si Hoppie falla, reintentos a los 30 s y a los 120 s; al tercer fallo queda «error» en el historial. flt.msgStatus/msgBodies/msgSentAt
// hacen que la tarjeta y el historial lo sigan como cualquier otro mensaje (enviado → recibido).
// Varias ventanas del OPS reciben las mismas muestras (la embebida en el ACARS y otra abierta aparte): solo envía la que tiene el monitor
// en marcha, y antes de enviar se relee el registro compartido y se reserva el envío (OOOI_CLAIM_MS) para que otra ventana no lo repita.
const OOOI_DEDUP_MS = 6 * 3600000, OOOI_RETRY_MS = [30000, 120000], OOOI_CLAIM_MS = 60000;
async function opsOooiSend(flt, ev, attempt = 0, body = null) {
  if (!$('oooiTx')?.checked) return;
  const cs = flt.callsign, key = 'oooi_' + ev.toLowerCase();
  if (!attempt && !monitorInterval) { log(`OOOI TELEX ${cs} ${ev}: no enviado, el monitor de esta ventana está detenido`, ''); return; }
  // La clave de dedup lleva la pierna (flt.firstSeen, que sobrevive a la recarga): una pierna nueva del mismo callsign dentro de las 6 h no la hereda
  // La reserva (60 s) no lleva firstSeen: dos ventanas que detectaron el vuelo por su cuenta tienen firstSeen distintos y no se verían;
  // en 60 s una pierna nueva no puede repetir el mismo evento. Un reintento tras fallo no mira el monitor (ya pasó el control al empezar).
  const dkey = `${key}_${flt.firstSeen || 0}`, claim = dedupKey(cs, flt.dep, flt.arr, key) + '~envio';
  reloadSentRegistry();
  if (wasSentRecently(cs, flt.dep, flt.arr, dkey, OOOI_DEDUP_MS)) { log(`OOOI TELEX omitido (dedup) ${cs} ${ev}`, 'ops'); return; }
  if (!attempt && Date.now() - (sentRegistry[claim] || 0) < OOOI_CLAIM_MS) { log(`OOOI TELEX omitido (otra ventana del OPS lo está enviando) ${cs} ${ev}`, 'ops'); return; }
  sentRegistry[claim] = Date.now(); saveSentRegistry(); // síncrono hasta aquí: otra ventana del mismo hilo ya ve la reserva
  body = body || NBV.oooi.telexText(cs, flt.dep, flt.arr, flt.oooi, ev);
  const f = () => flights[cs] || flt; // el escaneo sustituye el objeto del vuelo: se anota siempre en el vigente
  // Como los LANDED (processMessages): si el avión ya no está en Hoppie, el IN se retiene; la tarjeta permite enviarlo a mano
  if (ev === 'IN' && !(await opsAircraftOnline(cs))) {
    const g = f(); g.msgStatus[key] = 'held'; (g.msgBodies ||= {})[key] = body;
    log(`OOOI IN ${cs}: retenido, el avión ya no está conectado a Hoppie (clic en la tarjeta para enviarlo)`, 'wrn');
    recordSent(cs, g.dep, g.arr, dkey, key, 'held', body, key);
    updateDashboard();
    return;
  }
  try {
    await sendTelex(cs, body, { auto: true });
  } catch (e) {
    if (attempt < OOOI_RETRY_MS.length) {
      log(`OOOI ${cs} ${ev}: Hoppie falló (${e.message}), reintento en ${OOOI_RETRY_MS[attempt] / 1000} s`, 'wrn');
      setTimeout(() => opsOooiSend(f(), ev, attempt + 1, body), OOOI_RETRY_MS[attempt]);
      return;
    }
    const g = f(); g.msgStatus[key] = 'error'; (g.msgBodies ||= {})[key] = body; // la tarjeta permite reintentarlo a mano (manualSend)
    log(`✗ OOOI ${ev} → ${cs}: ${e.message}`, 'err');
    recordSent(cs, g.dep, g.arr, dkey, key, 'error', body, key);
    return;
  }
  const g = f(); g.msgStatus[key] = 'sent'; (g.msgBodies ||= {})[key] = body; (g.msgSentAt ||= {})[key] = Date.now();
  log(`✓ OOOI ${ev} → ${cs}`, 'ok');
  recordSent(cs, g.dep, g.arr, dkey, key, 'sent', body, key);
}
